/**
 * Pure (IO-free) generator: bridges[] → mosquitto conf-string for
 * `/etc/mosquitto/conf.d/mqtt-master-bridges.conf`.
 * Re-validates the bits that affect output safety: connection-name regex,
 * direction/qos, and rejects \r/\n in any field (config-injection guard,
 * T-3sd-01). No fs / child_process imports.
 */

const CONNECTION_NAME_RE = /^[a-zA-Z0-9_-]{1,64}$/;
const VALID_DIRECTIONS = new Set(['in', 'out', 'both']);
const VALID_QOS = new Set([0, 1, 2]);
const CONTROL_CHAR_RE = /[\r\n]/;

const HEADER = [
  '# Generated by mqtt-master — do not edit by hand',
  '# Source: config.json: bridges[*]',
  '',
].join('\n');

function assertNoNewline(field, value) {
  if (typeof value !== 'string') return;
  if (CONTROL_CHAR_RE.test(value)) {
    throw new Error(`Invalid ${field}: contains newline / CR / LF (config-injection guard)`);
  }
}

function validateConnectionName(name) {
  if (typeof name !== 'string' || !CONNECTION_NAME_RE.test(name)) {
    throw new Error(`Invalid connection name: "${name}"`);
  }
}

function validateTopicLine(t) {
  if (!t || typeof t !== 'object') {
    throw new Error('Invalid topic line: not an object');
  }
  if (typeof t.pattern !== 'string' || t.pattern.length === 0) {
    throw new Error('Invalid topic line: missing pattern');
  }
  assertNoNewline('topic pattern', t.pattern);
  if (!VALID_DIRECTIONS.has(t.direction)) {
    throw new Error(`Invalid topic direction: "${t.direction}" (expected in/out/both)`);
  }
  if (!VALID_QOS.has(t.qos)) {
    throw new Error(`Invalid topic qos: ${t.qos} (expected 0/1/2)`);
  }
}

/**
 * Render a single bridge's lines (without surrounding blank lines).
 * Returns an array of strings (one per line, NO trailing blank).
 */
function renderBridgeLines(bridge) {
  validateConnectionName(bridge.connectionName);
  // Host + port are not emitted into config as separate tokens that could be
  // newline-attacked, but the `address` line includes the host verbatim — so
  // we still guard it.
  assertNoNewline('remoteHost', bridge.remoteHost);
  if (typeof bridge.remoteHost !== 'string' || bridge.remoteHost.length === 0) {
    throw new Error('Invalid remoteHost: must be a non-empty string');
  }
  if (!Number.isInteger(bridge.remotePort) || bridge.remotePort < 1 || bridge.remotePort > 65535) {
    throw new Error(`Invalid remotePort: ${bridge.remotePort}`);
  }
  const lines = [
    `connection ${bridge.connectionName}`,
    `address ${bridge.remoteHost}:${bridge.remotePort}`,
    `remote_clientid mqtt-master-bridge-${bridge.connectionName}`,
    'cleansession false',
    'notifications false',
    'try_private true',
    'bridge_protocol_version mqttv311',
  ];

  // Auth lines: emit only when remoteUsername is truthy (non-empty).
  if (bridge.remoteUsername && typeof bridge.remoteUsername === 'string') {
    assertNoNewline('remoteUsername', bridge.remoteUsername);
    assertNoNewline('remotePassword', bridge.remotePassword || '');
    lines.push(`remote_username ${bridge.remoteUsername}`);
    lines.push(`remote_password ${bridge.remotePassword || ''}`);
  }

  // Topic lines: one per pattern, order-preserving.
  if (!Array.isArray(bridge.topics) || bridge.topics.length === 0) {
    throw new Error(`Bridge "${bridge.connectionName}" has no topics`);
  }
  for (const t of bridge.topics) {
    validateTopicLine(t);
    lines.push(`topic ${t.pattern} ${t.direction} ${t.qos} "" ""`);
  }
  return lines;
}

/**
 * Generate the full mosquitto conf-string for the given bridges array.
 * Throws on validation failures so we never write a corrupt file.
 */
export function generateMosquittoBridgeConf(bridges) {
  if (!Array.isArray(bridges)) {
    throw new Error('bridges must be an array');
  }

  // Pre-validate connection-name uniqueness so a duplicate produces a
  // deterministic error rather than a silently broken .conf.
  const seen = new Set();
  for (const b of bridges) {
    const name = b && b.connectionName;
    if (typeof name === 'string') {
      if (seen.has(name)) {
        throw new Error(`Duplicate connection name: "${name}"`);
      }
      seen.add(name);
    }
  }

  if (bridges.length === 0) {
    return HEADER;
  }

  const blocks = bridges.map((bridge) => {
    const enabled = bridge.enabled !== false; // default true
    const inner = renderBridgeLines(bridge);
    if (enabled) {
      return inner.join('\n');
    }
    const commented = inner.map((line) => (line.length > 0 ? `# ${line}` : '#'));
    return [`# DISABLED: ${bridge.connectionName}`, ...commented].join('\n');
  });

  return HEADER + blocks.join('\n\n') + '\n';
}
